void __stdcall MCPCONNECT_SanitizeWideString(uint16_t * wszText) {
    uint16_t* wszMatch;
    int32_t iVar1;
    int32_t nLen = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(wszText);
    if (!(nLen < 500)) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x342);
      exit(-1);
    }

    {
      uint16_t* wszToken;
      wszToken = D2Lang::StrTable::strtable::GetLocaleString(0xf9a);
      nLen = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(wszToken);
      wszMatch = (uint16_t*)D2Lang::Unicode::UNISYS::UNICODE_FindSubstring((uint16_t*)wszText, (uint16_t*)wszToken);
      while (wszMatch && wszMatch[nLen] != L'\0') {
        iVar1 = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(wszMatch);
        memmove(wszMatch, wszMatch + nLen + 1, (iVar1 - nLen) * 2);
        wszMatch = (uint16_t*)D2Lang::Unicode::UNISYS::UNICODE_FindSubstring((uint16_t*)wszText, (uint16_t*)wszToken);
      }

      return;
    }
}

// MCP 0x05 reply handler = REALM GAMELIST entry (one game per packet) AND join-info.
// Stores into g_CharSelectBuffer struct (base 0x799108); JoinOrCreateGame polls it and
// calls OOGMENU_AddGameToCache per game, refreshing the JOIN-screen list.
// Wire payload (pBytes[0]=type 0x05):
//   +0   u8   0x05 type
//   +1   u16  reqid  (must == nMcpPacketSequence @0x798f8c, the request seq)
//   +3   u32  field  -> g_CharSelectBuffer+0x08 (low u16 = gameid, AddGameToCache dedup key)
//   +7   u8   status -> g_CharSelectBuffer+0x14 (zero-ext; AddGameToCache reads u16)
//   +8   u32  token  -> g_CharSelectBuffer+0x18.  token==-1 -> SetD2GSJoinResult(0x32);
//                      token==-2 -> SetD2GSJoinResult(0x33) = END-OF-LIST -> RefreshGameListDisplay()
//   +0xc cstr name   -> g_CharSelectBuffer+0x1c (game name, shown in list)
//        cstr desc   -> g_CharSelectBuffer+0x2c (description)
// g_CharSelectBuffer+0 = 1 if bytes remain after this game's 2 strings, else 0.
// JoinOrCreateGame adds the game only when that flag==0 (i.e. exactly one game per packet).
// => realm game list = N per-game 0x05 packets + a final 0x05 packet with token=-2.
// This is NOT one concatenated packet, and NOT BNCS SID_GETADVLISTEX (that path is TCP/IP
// only, via OOGUTIL_RequestGameListFromServer / g_pBNetGameListData).
BOOL __fastcall NET_MCP_CLIENT_Incoming0x05(char * pBytes, size_t nSize) {
    char* pCursor2;
    char szServerName[1024];
    uint16_t wszServerName[576];
    char cChar;
    uint32_t dwJoinStatusPart5 = *(uint32_t*)(pBytes + 3);
    int nJoinToken = *(int*)(pBytes + 8);
    if (*(uint16_t*)(pBytes + 1) != nMcpPacketSequence) {
      return 1;
    }

    g_CharSelectBuffer.wRequestId = nMcpPacketSequence;
    g_CharSelectBuffer.nPlayerCount = (int32_t)(uint8_t)pBytes[7];
    g_CharSelectBuffer.dwGameId = dwJoinStatusPart5;
    g_CharSelectBuffer.nGameToken = nJoinToken;
    size_t nSizeCopy = nSize;
    if (nJoinToken == -2) {
      SetD2GSJoinResult(0x33);
      return 1;
    }
    if (nJoinToken == -1) {
      SetD2GSJoinResult(0x32);
      return 1;
    }

    char* pCharName = pBytes + 0xc;
    char* pCursor = pCharName;
    do {
      cChar = *pCursor;
      pCursor++;
      pCursor2 = pCursor;
    } while (cChar != '\0');

    pCursor2 = pCursor2 + strlen(pCursor2) + 1;
    Fog::File::CONTAINER_InitializeBuffer(wszServerName, 2, 0x240, D2Launch::MainMenus::STRING_ZeroOneWCHAR);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszServerName, pCharName, 0x240);
    MCPCONNECT_SanitizeWideString(wszServerName);
    D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte(szServerName, (uint16_t*)wszServerName, 0x400);
    Storm::Source::SSTR::SStrCopy(g_CharSelectBuffer.szGameName, szServerName, 0x10);
    Storm::Source::SSTR::SStrCopy(g_CharSelectBuffer.szGameDescription, pCursor, 0x10);
    g_CharSelectBuffer.nHasMoreData = (int)((uint32_t)((int)pCursor2 - (int)pBytes) < nSizeCopy);
    return 1;
}

